(441988, 40676, 327, '<td valign="top">Tetons? A wonderfully rich, vibrant stunning shot. This is a poster and a winner for sure. Very good work.</td>', 'Tetons? A wonderfully rich, vibrant stunning shot. This is a poster and a winner for sure. Very good work.', '2003-10-08 01:03:04.000000', NULL, 1),
(441994, 40676, 7969, '<td valign="top">well, there is a building, not a real urban feel IM), but a beautiful shot, nice light.</td>', 'well, there is a building, not a real urban feel IM), but a beautiful shot, nice light.', '2003-10-08 01:05:19.000000', NULL, 1),
(441995, 41370, 2333, '<td valign="top">Ah, recent memories, I was there two weeks ago...</td>', 'Ah, recent memories, I was there two weeks ago...', '2003-10-08 01:05:41.000000', NULL, 1),
