(442968, 41292, 10673, '<td valign="top">Wonderful!  10</td>', 'Wonderful!  10', '2003-10-08 11:48:11.000000', NULL, 1),
(442969, 41177, 327, '<td valign="top">Very rich looking tones and light. Love the lamp post and the woman on the right. Nice eye for a good shot!!!!</td>', 'Very rich looking tones and light. Love the lamp post and the woman on the right. Nice eye for a good shot!!!!', '2003-10-08 11:48:29.000000', NULL, 1),
