(443202, 40681, 6845, '<td valign="top">Nice colors.</td>', 'Nice colors.', '2003-10-08 13:08:17.000000', NULL, 1),
(443203, 41301, 12733, '<td valign="top">A nice, colorful street, well composed and lighted. The fringe of branches framing the top saves the picture from a monotonous grey sky.</td>', 'A nice, colorful street, well composed and lighted. The fringe of branches framing the top saves the picture from a monotonous grey sky.', '2003-10-08 13:08:35.000000', NULL, 1),
(443206, 40653, 6845, '<td valign="top">I like this image. Nice composition.</td>', 'I like this image. Nice composition.', '2003-10-08 13:08:55.000000', NULL, 1),
(443207, 40983, 6845, '<td valign="top">Great color. Nice composition. This is a very nice image.</td>', 'Great color. Nice composition. This is a very nice image.', '2003-10-08 13:09:38.000000', NULL, 1),
(443208, 41102, 11241, '<td valign="top">love the shape of the building and the color of the sky...great shot</td>', 'love the shape of the building and the color of the sky...great shot', '2003-10-08 13:09:42.000000', NULL, 1),
(443210, 40887, 12733, '<td valign="top">Nice sky and silhouette, pretty composition.</td>', 'Nice sky and silhouette, pretty composition.', '2003-10-08 13:09:57.000000', NULL, 1),
(443211, 40678, 11241, '<td valign="top">it is too bad the cars are there....but still very nice shot</td>', 'it is too bad the cars are there....but still very nice shot', '2003-10-08 13:10:11.000000', NULL, 1),
(443213, 41024, 12733, '<td valign="top">Great sky, interesting building. I normally don''t like to see part of a structure cut off, but this works well to emphasize the sky.</td>', 'Great sky, interesting building. I normally don''t like to see part of a structure cut off, but this works well to emphasize the sky.', '2003-10-08 13:11:31.000000', NULL, 1),
(443215, 41046, 6845, '<td valign="top">That is one funky building. I personally would have liked to see this image with out the larger flower that is out of focus. It is a bit distracting.</td>', 'That is one funky building. I personally would have liked to see this image with out the larger flower that is out of focus. It is a bit distracting.', '2003-10-08 13:11:45.000000', NULL, 1),
(443217, 41216, 6405, '<td valign="top">Your lense have spots,make sure it''s clean before use.</td>', 'Your lense have spots,make sure it''s clean before use.', '2003-10-08 13:11:59.000000', NULL, 1),
(443218, 41024, 9913, '<td valign="top">nice spooky athmosphere here, would have liked to see the top of the tower though</td>', 'nice spooky athmosphere here, would have liked to see the top of the tower though', '2003-10-08 13:12:11.000000', NULL, 1),
