(443221, 41218, 6845, '<td valign="top">Nice night time image. The lights are great.</td>', 'Nice night time image. The lights are great.', '2003-10-08 13:12:42.000000', NULL, 1),
(443222, 41262, 6845, '<td valign="top">This is a nice graphic image.</td>', 'This is a nice graphic image.', '2003-10-08 13:13:01.000000', NULL, 1),
