(447960, 40682, 12848, '<td valign="top">I would have loved to see the color version of this picture.</td>', 'I would have loved to see the color version of this picture.', '2003-10-12 20:06:42.000000', NULL, 1),
(447962, 41289, 12809, '<td valign="top">This is a great shot.  Love how the buildings are staggered in size, the colors are nice, and the tall crop works very well.</td>', 'This is a great shot.  Love how the buildings are staggered in size, the colors are nice, and the tall crop works very well.', '2003-10-12 20:07:13.000000', NULL, 1),
