(450658, 41309, 4615, '<td valign="top">when did "S" become "/"?</td>', 'when did "S" become "/"?', '2003-10-14 23:59:39.000000', NULL, 1),
(450659, 40829, 9441, '<td valign="top">Terrific DOF!!  And fabulous clear color.  Very sharp, and a wonderful crispness to this photo.  I love the way you caputured all the angles, and such a wonderful composition and crop!!</td>', 'Terrific DOF!!  And fabulous clear color.  Very sharp, and a wonderful crispness to this photo.  I love the way you caputured all the angles, and such a wonderful composition and crop!!', '2003-10-14 23:59:53.000000', NULL, 1),
(450660, 41178, 7570, '<td valign="top">not balanced cropping between top and bottom of subject (the city)<br/>try cropping more off the top, or leave more on the bottom. 7</td>', 'not balanced cropping between top and bottom of subject (the city)try cropping more off the top, or leave more on the bottom. 7', '2003-10-15 00:01:19.000000', NULL, 1),
(450661, 41226, 11610, '<td valign="top">Great Juxtaposition</td>', 'Great Juxtaposition', '2003-10-15 00:01:36.000000', NULL, 1),
(450662, 40867, 9441, '<td valign="top">Awesome photo!  Lots of wonderful detail...very crisp and sharp.  Wonderful lighting...terrific composition...simply fantastic...a for sure 10!</td>', 'Awesome photo!  Lots of wonderful detail...very crisp and sharp.  Wonderful lighting...terrific composition...simply fantastic...a for sure 10!', '2003-10-15 00:01:45.000000', NULL, 1),
(450663, 40754, 11610, '<td valign="top">vibrant photo</td>', 'vibrant photo', '2003-10-15 00:02:05.000000', NULL, 1),
